    public const string PacketId="R6-O01:extra-packet",PressId="R6-O02:shared-press",LampId="R6-O02:borrowed-lamp";
    public const string PacketTask="R6-O01-W-WEATHER",PressTask="R6-O02-W-MAINTENANCE",LampTask="R6-O02-W-LAMP";
    public static readonly ImmutableArray<string> PacketSerials=["R6-O01-SCREEN-01","R6-O01-SCREEN-02","R6-O01-SEAL-01"];
    public const string Stock="R6-S05:optional-local-stock",Receiver="ROLE-R6-O01-RECEIVER",PressSerial="R6-O02-PRESS-01",Workshop="R6-O02:shared-workshop";
    public const string LampSerial="R6-O02-LAMP-01",LampOwner="ROLE-R6-O01-LAMP-OWNER",LampBorrower="ROLE-R6-O02-LAMP-BORROWER";
    private readonly IAdventureRepository _repository;private readonly ChapterSixService _chapter;private readonly Dictionary<Guid,CommitPlanCommand> _previews=[];
    public SettlementSupportContract Contract {get;}
    public SettlementSupportService(IAdventureRepository repository,ChapterSixService chapter,SettlementSupportContract contract)
    {
        _repository=repository;_chapter=chapter;Contract=contract;Require(contract.Version=="r6-settlement-support-candidate-2"&&contract.Sections.Length==2,"局部合同版本未绑定。");
        foreach(var section in contract.Sections)Require(chapter.Geometry[section.Scene].Spots.Any(p=>p.Id==section.Spot),"聚落须使用原真实几何站位。");
        Require(contract.Sections[0].Paragraphs.Any(p=>p.English.Contains("earlier_arrival_stage",StringComparison.Ordinal))&&contract.Sections[1].Paragraphs.Any(p=>p.English.Contains(LampSerial,StringComparison.Ordinal)),"两份有窗口的预报与原同灯合同未公开，不能补造私人源。");
    }
    private static void Require(bool v,string text){if(!v)throw new InvalidOperationException(text);}
    private static T? Read<T>(BranchSnapshot s,string id) where T:class=>BranchOperations.Read<T>(s,id);
    private void Allowed(BranchSnapshot s)
    {
        BranchOperations.Safe(s);Require(!s.Entities.Where(e=>e.Kind=="event").Select(e=>StrictJson.Deserialize<EventSession>(e.Json)).Any(e=>e.State==EventLifecycle.Running),"另一前景事件尚未交接。");
        Require(!s.Entities.Where(e=>e.Kind=="transport_segment").Select(e=>StrictJson.Deserialize<TransportSegment>(e.Json)).Any(t=>t.CargoInTransit&&!t.Completed),"先安全交接受保护的实际货组。");
        Require(!BranchOperations.Receipt(s,"Q-604")&&BranchOperations.Entity(s,"final:preparation") is null,"准备封存或最终起航后本地追加工作暂停。");
        var st=Read<ChapterSixState>(s,"chapter6");var q=Read<QuestState>(s,"quest:Q-601");Require(st is{Landing:true,Briefing:true,BasicGear:true}&&st.ContentVersion==_chapter.Package.Version&&st.SurveyCurrent&&q is{Lifecycle:QuestLifecycle.Closed,Outcome:QuestOutcome.Completed}&&s.Receipts.Any(r=>r.SemanticKey=="Q-601:resolution"),"先实际登陆并核验当前调查、基础保护与Q601真实交接；可选任务不替主线。");
    }
    private void At(BranchSnapshot s,string spot)
    {var a=Read<ActorState>(s,"actor")??throw new InvalidOperationException("角色现场未加载。");var scene=spot.Split('.')[0];var g=_chapter.CurrentGeometry(s)[scene];Require(a.Scene==scene&&a.Position.Distance(g.Spots.Single(x=>x.Id==spot).Stand)<=2.5&&new NavigationGrid(g).CanStand(a.Position,true),"请先实际走到本地对应安全站位。");}
    private string Access(string id)=>"material:R6-LOCAL-"+id;
    private bool Acquired(BranchSnapshot s,string id)=>BranchOperations.Entity(s,Access(id))?.Json==StrictJson.Serialize(new{version=Contract.Version,fingerprint=Contract.Fingerprint,id});
    private void Source(BranchSnapshot s,string id)=>Require(Acquired(s,id),"公开局部原件须实际到场取得，不能以目录或未访地材料代替。");
    public async ValueTask<SettlementSupportView> ViewAsync(){var s=await _repository.SnapshotAsync();return new(s,Read<SettlementPacketState>(s,PacketId),Read<SharedPressState>(s,PressId),Read<BorrowedLampState>(s,LampId),Contract.Sections.Where(x=>Acquired(s,x.Id)).Select(x=>x.Id).ToImmutableArray());}
    public async ValueTask<SettlementSupportSection> OpenContractAsync(string id){var s=await _repository.SnapshotAsync();Source(s,id);return Contract.Sections.Single(x=>x.Id==id);}
    public async ValueTask<CommandResult> DiscoverAsync(string id)
    {var s=await _repository.SnapshotAsync();Allowed(s);var section=Contract.Sections.Single(x=>x.Id==id);At(s,section.Spot);if(Acquired(s,id))return new(CommitStatus.AlreadyCommitted,null,[]);string original=id=="O-R6-01"?"R6-O01-R-NEEDS":"R6-O02-R-MAINTENANCE";Require(BranchOperations.Entity(s,"material:"+original) is not null,"先在原主线材料入口实际取得该公开告示。");return await Execute(Plan(s,Access(id)+":acquired","settlement_public_contract_acquired",new{version=Contract.Version,fingerprint=Contract.Fingerprint,id,private_source_supplied=false},[BranchOperations.Change(s,Access(id),"optional_material_access",new{version=Contract.Version,fingerprint=Contract.Fingerprint,id})]));}
    private string[] Reads(BranchSnapshot s)=>s.Entities.Select(e=>e.Id).Concat(new[]{PacketId,PressId,LampId,Access("O-R6-01"),Access("O-R6-02"),PacketId+":comparison",PressId+":permission",PressId+":reserve",PressId+":zero",LampId+":zero",PacketId+":meaning",PressId+":meaning",LampId+":meaning",PacketId+":result",PressId+":result",LampId+":result", "final:preparation"}).Distinct().ToArray();
    private static bool LocalItem(StoredItem item)=>PacketSerials.Contains(item.Id)||item.Id==PressSerial||item.Id==LampSerial||item.Id.StartsWith("R6-O02-MANUAL-",StringComparison.Ordinal);
    private CommitPlanCommand Plan(BranchSnapshot s,string key,string action,object payload,ImmutableArray<EntityChange> changes,ImmutableArray<ItemChange> items=default,DraftStamp? draft=null)
    {var claims=(items.IsDefault?ImmutableArray<ItemChange>.Empty:items).ToBuilder();foreach(var i in s.Items.Where(LocalItem))if(!claims.Any(x=>x.Id==i.Id))claims.Add(new(i.Id,i.DefinitionId,i.OwnerKind,i.OwnerId,i.OwnerKind,i.OwnerId,i.Slot));return BranchOperations.Plan(_repository,s,key,action,changes,Reads(s),payload,items:claims.ToImmutable(),draft:draft);}
    private async ValueTask<CommandResult> Execute(CommitPlanCommand c)
    {var ses=_repository.Session;if(c.Context.Profile!=ses.Profile||c.Context.Branch!=ses.Branch||c.Context.Load!=ses.Load||c.Context.ReleaseId!=ses.ReleaseId)return new(CommitStatus.Rejected,null,[new("stale_load",PacketId,"读取世代已变，请重新核对本地工作。")]);if(_repository is not IEventLeaseStore lease)throw new InvalidOperationException("本地派工须原子前景占用。");string owner="settlement:"+c.Context.Command.Value;Require(await lease.TryLeasesAsync(ses.Load,owner,["input:foreground"]),"另一前景工作尚未交接。");try{return await _repository.ExecuteAsync(c);}finally{await lease.ReleaseLeasesAsync(ses.Load,owner);}}
    private StoredItem Item(BranchSnapshot s,string serial,string definition,string kind,string owner)
    {var i=s.Items.SingleOrDefault(x=>x.Id==serial);Require(i is not null&&i.DefinitionId==definition&&i.OwnerKind==kind&&i.OwnerId==owner,"原同一有限实物、规格或保管地不符，不用另一批替代。");return i!;}
    private SettlementPacketState Packet(BranchSnapshot s)
    {Source(s,"O-R6-01");var st=Read<SettlementPacketState>(s,PacketId);Require(st is not null&&st.Fingerprint==Contract.Fingerprint&&st.Decision=="accept"&&!st.Delivered,"追加运输未明确接受、源版本已变或已交付。");return st!;}
    public async ValueTask<CommandResult> DecidePacketAsync(string decision)
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R6-O01.notice");Source(s,"O-R6-01");Require(decision is "accept" or "defer" or "decline","明确接受、暂缓或拒绝这一追加运输。");var old=Read<SettlementPacketState>(s,PacketId);Require(old is null||old.Fingerprint==Contract.Fingerprint&&!old.Delivered&&!old.Dispatched,"已派运或已交付同批不能重置。");var st=old is null?new SettlementPacketState(Guid.NewGuid(),Contract.Fingerprint,decision):old with{Decision=decision};return await Execute(Plan(s,PacketId+":decision:"+Guid.NewGuid(),"settlement_optional_transport_decided",new{decision,scope="local_extra_packet_only",no_ending_key=true},[BranchOperations.Change(s,PacketId,"optional_local_packet",st)]));}
    public async ValueTask<CommandResult> CompareForecastsAsync(string passStage,string localPlace,string localStage,string corridor,string fallback)
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R6-O01.notice");var st=Packet(s);Require(!st.Dispatched&&passStage=="current_survey_stage"&&localPlace=="southern_inlet"&&localStage=="earlier_arrival_stage"&&corridor=="marked_leeward"&&fallback=="sheltered_return","预报的地点与窗口须分开；较早南部清亮不能推翻当前山口积雾与阵风。");var m=_chapter.Package.Materials.Single(x=>x.Id=="R6-Q601-R-FORECAST");Require(BranchOperations.Entity(s,"material:"+m.Id)?.Json==StrictJson.Serialize(new Mist.Core.ChapterTwo.ChapterMaterialAccess(m.Id,m.Version,m.TranslationVersion,m.Fingerprint,m.SourceRoot,m.Spot))&&Read<ChapterSixState>(s,"chapter6")?.Corridor==corridor,"当前预报原件和实际山口路线未成立。");var body=new{pass_stage=passStage,local_place=localPlace,local_stage=localStage,corridor,fallback,source=Contract.Fingerprint};return await Execute(Plan(s,PacketId+":comparison:"+Guid.NewGuid(),"settlement_two_forecasts_compared",body,[BranchOperations.Change(s,PacketId,"optional_local_packet",st with{Comparison=true}),BranchOperations.Change(s,PacketId+":comparison","optional_forecast_comparison",body)]));}
    public async ValueTask<CommandResult> InspectExtraStockAsync(string[] serials)
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R6-S05.manifest");var st=Packet(s);Require(st.Comparison&&!st.Dispatched&&serials.SequenceEqual(PacketSerials),"先核两份预报，并逐件检查这三件额外序号；不得挪用基础或五箱补充。");if(st.StockInspected){foreach(var id in PacketSerials)Item(s,id,id.Contains("SCREEN",StringComparison.Ordinal)?"R6-LOCAL-WIND-SCREEN":"R6-LOCAL-SEAL-PACK","warehouse",Stock);return new(CommitStatus.AlreadyCommitted,null,[]);}Require(!s.Items.Any(i=>PacketSerials.Contains(i.Id)),"有限库存已有不完整旧来源，不能再补造。");var items=PacketSerials.Select(id=>new ItemChange(id,id.Contains("SCREEN",StringComparison.Ordinal)?"R6-LOCAL-WIND-SCREEN":"R6-LOCAL-SEAL-PACK","new","","warehouse",Stock,null)).ToImmutableArray();return await Execute(Plan(s,PacketId+":stock","settlement_finite_extra_stock_inspected",new{serials,source=Contract.Fingerprint,owner=Stock,protected_resources_used=false},[BranchOperations.Change(s,PacketId,"optional_local_packet",st with{StockInspected=true})],items));}
    public async ValueTask<CommandResult> DispatchPacketAsync(string[] serials,string driver,string watch)
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R6-S05.manifest");var st=Packet(s);Require(st.StockInspected&&st.Comparison&&!st.Dispatched&&serials.SequenceEqual(PacketSerials)&&driver=="ROLE-R6-CART-DRIVER"&&watch=="ROLE-R6-CARGO-WATCH"&&Read<ChapterSixState>(s,"chapter6") is{CargoDelivered:true,CargoPlan:not null} ch&&ch.CargoPlan.Escorts.Contains(driver)&&ch.CargoPlan.Escorts.Contains(watch),"实际受保护货组先交接，并由原两个不同当地岗位接收追加运输；未招募同伴不自动任职。");foreach(var id in PacketSerials)Item(s,id,id.Contains("SCREEN",StringComparison.Ordinal)?"R6-LOCAL-WIND-SCREEN":"R6-LOCAL-SEAL-PACK","warehouse",Stock);var a=Read<ActorState>(s,"actor")!;return await Execute(Plan(s,PacketId+":dispatch","settlement_optional_packet_dispatched",new{serials,driver,watch,origin="R6-S05",destination="R6-O01",fallback="sheltered_return",instance=st.Instance},[BranchOperations.Change(s,PacketId,"optional_local_packet",st with{Dispatched=true,DispatchSequence=s.Sequence+1,DispatchClock=a.ActionClock})],PacketSerials.Select(id=>new ItemChange(id,id.Contains("SCREEN",StringComparison.Ordinal)?"R6-LOCAL-WIND-SCREEN":"R6-LOCAL-SEAL-PACK","warehouse",Stock,"warehouse",PacketId+":courier",null)).ToImmutableArray()));}
    private ImmutableArray<string> ActualRoute(BranchSnapshot s,long after,string from,string to)
    {var traces=s.Receipts.Where(r=>r.Sequence>after&&r.ActionType=="scene_transition").OrderBy(r=>r.Sequence).ToArray();string current=from;long clock=-1;var ids=ImmutableArray.CreateBuilder<string>();foreach(var r in traces){var t=StrictJson.Deserialize<TraversedConnection>(r.ResultJson);Require(t.From==current&&t.ActionClock>clock&&t.GateReads.All(g=>(BranchOperations.Entity(s,g.EntityId)?.Revision??-1)==g.Revision),"本批实际遍历或当前安全来源不连续，旧到访不算到货。");var geo=_chapter.CurrentGeometry(s);Require(geo.TryGetValue(t.From,out var a)&&geo.TryGetValue(t.To,out var b)&&a.Ports.Any(p=>p.Id==t.FromPort&&p.TargetScene==t.To&&p.TargetPort==t.ToPort)&&b.Ports.Any(p=>p.Id==t.ToPort&&p.TargetScene==t.From),"遍历须是原配对连接，不能凭空航行。");current=t.To;clock=t.ActionClock;ids.Add(r.ReceiptId);}Require(current==to&&ids.Count>0&&Read<ActorState>(s,"actor")?.Scene==to,"本批尚未沿当前路线真正抵达接收聚落。");return ids.ToImmutable();}
    public async ValueTask<DraftSaved> SaveDraftAsync(string task,long revision,DraftId? draft,string body)
    {Require(task is PacketTask or PressTask or LampTask,"未登记的本地稿件。");var ses=_repository.Session;return await _repository.SaveAsync(new(ses.Profile,ses.Branch,ses.Load,task,draft,revision,body,Contract.Version));}
    private static string StateFor(string task)=>task switch{PacketTask=>PacketId,PressTask=>PressId,LampTask=>LampId,_=>throw new InvalidOperationException("本地稿件未登记。")};
    public async ValueTask<CommandResult> ConfirmMeaningAsync(string task,ImmutableDictionary<string,string> fields,bool assisted)
    {var s=await _repository.SnapshotAsync();Allowed(s);string id=StateFor(task);At(s,task==PacketTask||task==LampTask&&Read<BorrowedLampState>(s,LampId) is{Returned:true}?"R6-O01.notice":"R6-O02.notice");Source(s,task==PacketTask?"O-R6-01":"O-R6-02");var d=await _repository.GetDraftAsync(task)??throw new InvalidOperationException("正文尚未实际保存。");Require(!d.Deleted&&!string.IsNullOrWhiteSpace(d.Body),"保存正文与意思确认分层，空稿不能被选项代替。");return await Execute(Plan(s,id+":meaning:"+Guid.NewGuid(),"settlement_local_note_meaning_confirmed",new{task,assisted,free_english_understanding="not_claimed",language_score=(string?)null},[BranchOperations.Change(s,id+":meaning","optional_note_meaning",new SettlementNoteMeaning(d.Hash,assisted,fields))],draft:new(task,d.Id,d.Revision,d.Hash)));}
    private async ValueTask<(DraftView Draft,SettlementNoteMeaning Meaning)> Note(string task,params (string Key,string Value)[] expected)
    {var s=await _repository.SnapshotAsync();var d=await _repository.GetDraftAsync(task)??throw new InvalidOperationException("正文未保存。");var m=Read<SettlementNoteMeaning>(s,StateFor(task)+":meaning");Require(!d.Deleted&&!string.IsNullOrWhiteSpace(d.Body)&&m is not null&&m.DraftHash==d.Hash&&expected.All(e=>m.Fields.TryGetValue(e.Key,out var actual)&&actual==e.Value),"当前保存稿件意思未逐项核对，或正文、窗口、归属、边界有变。");return(d,m!);}
    private static string EvidenceId(BranchSnapshot s,string action,string? body=null)=>s.Receipts.Where(r=>r.ActionType==action&&(body is null||r.ResultJson==body)).OrderByDescending(r=>r.Sequence).FirstOrDefault()?.ReceiptId??throw new InvalidOperationException("实际来源回执缺失。");
    private SettlementPreview Preview(CommitPlanCommand c,string task,string hash){var token=Guid.NewGuid();_previews[token]=c;return new(token,true,[],task,hash);}
    public async ValueTask<SettlementPreview> PreviewPacketDeliveryAsync()
    {var s=await _repository.SnapshotAsync();Allowed(s);At(s,"R6-O01.notice");var st=Packet(s);Require(st.Dispatched&&st.Comparison&&st.StockInspected,"尚未实际派运这同一批追加物资。");var route=ActualRoute(s,st.DispatchSequence,"R6-S05","R6-O01");foreach(var id in PacketSerials)Item(s,id,id.Contains("SCREEN",StringComparison.Ordinal)?"R6-LOCAL-WIND-SCREEN":"R6-LOCAL-SEAL-PACK","warehouse",PacketId+":courier");var note=await Note(PacketTask,("route","marked_leeward"),("fallback","sheltered_return"),("windows","different_places_and_stages"),("stock","three_optional_serials"),("scope","extra_only_no_ending"));var result=new SettlementPacketDelivery(st.Instance,Contract.Fingerprint,Receiver,PacketSerials,route,EvidenceId(s,"settlement_optional_packet_dispatched"),EvidenceId(s,"settlement_two_forecasts_compared",BranchOperations.Entity(s,PacketId+":comparison")!.Json),note.Draft.Hash,"optional_extra_only",0,0,0);return Preview(Plan(s,PacketId+":resolution","settlement_extra_packet_received",result,[BranchOperations.Change(s,PacketId,"optional_local_packet",st with{Delivered=true}),BranchOperations.Change(s,PacketId+":result","optional_local_delivery",result)],PacketSerials.Select(id=>new ItemChange(id,id.Contains("SCREEN",StringComparison.Ordinal)?"R6-LOCAL-WIND-SCREEN":"R6-LOCAL-SEAL-PACK","warehouse",PacketId+":courier","installed",Receiver,null)).ToImmutableArray(),new(PacketTask,note.Draft.Id,note.Draft.Revision,note.Draft.Hash)),PacketTask,note.Draft.Hash);}
    public ValueTask<CommandResult> ConfirmPreviewAsync(Guid token)=>_previews.TryGetValue(token,out var c)?Execute(c):ValueTask.FromResult(new CommandResult(CommitStatus.Rejected,null,[new("preview_closed",PacketId,"预览已取消，请重新核对。") ]));
